/**
 * BM25 postings and semantic embeddings for Frame Codex search, written to codex-search.json.
 *
 * @remarks
 * - Consumes codex-index.json (generated by scripts/auto-index.js)
 * - Generates codex-search.json with:
 *   - BM25 postings (term -> [docId, termFrequency])
 *   - Document metadata (path, title, summary, weave, loom, docLength)
 *   - Packed Float32 embeddings (all-MiniLM-L6-v2, mean pooled, normalized)
 * - Embeddings are stored as base64 Float32Array to keep payload compact.
 * - scripts/build-search-index.mjs runs it in CI after the auto-index step; tests/search-index.test.js runs it with a
 *   stand-in for the embedding model.
 */

import fs from 'fs'
import path from 'path'

export const STOP_WORDS = new Set([
  'the',
  'a',
  'an',
  'and',
  'or',
  'but',
  'in',
  'on',
  'at',
  'to',
  'for',
  'of',
  'with',
  'by',
  'from',
  'as',
  'is',
  'was',
  'are',
  'been',
  'be',
  'have',
  'has',
  'had',
  'do',
  'does',
  'did',
  'will',
  'would',
  'should',
  'could',
  'may',
  'might',
  'must',
  'can',
  'this',
  'that',
  'these',
  'those',
  'i',
  'you',
  'he',
  'she',
  'it',
  'we',
  'they',
  'what',
  'which',
  'who',
  'when',
  'where',
  'why',
  'how',
  'all',
  'each',
  'every',
  'both',
  'few',
  'more',
  'most',
  'other',
  'some',
  'such',
  'no',
  'nor',
  'not',
  'only',
  'own',
  'same',
  'so',
  'than',
  'too',
  'very',
  's',
  't',
  'just',
  'don',
  'now',
  'use',
  'using',
  'used',
])

export const tokenize = (text = '') =>
  text
    .toLowerCase()
    .replace(/[^\w\s]/g, ' ')
    .split(/\s+/)
    .filter((term) => term.length > 2 && !STOP_WORDS.has(term))

const deriveWeave = (filePath = '') => {
  const segments = filePath.split('/')
  return segments.length > 1 ? segments[1] : ''
}

const deriveLoom = (filePath = '') => {
  const segments = filePath.split('/')
  if (segments.length <= 3) return ''
  // Remove leading 'weaves' and weave slug, drop filename
  return segments.slice(2, -1).join('/')
}

/**
 * The BM25 postings and document list for the index entries, in their order: docs[docId] describes entries[docId], and
 * vocabulary maps each term, in sorted order, to its [docId, termFrequency] pairs.
 */
export function buildPostings(entries) {
  const docs = []
  const vocabulary = new Map()
  let totalLength = 0

  entries.forEach((entry, docId) => {
    const meta = entry.metadata || {}
    const title = meta.title || entry.name || entry.path
    const summary = meta.summary || ''
    const textSource = [title, summary, entry.content || ''].filter(Boolean).join('\n').slice(0, 8000)

    const tokens = tokenize(textSource)
    const docLength = tokens.length || 1
    totalLength += docLength

    docs.push({
      path: entry.path,
      title,
      summary,
      weave: deriveWeave(entry.path),
      loom: deriveLoom(entry.path),
      docLength,
    })

    const termFrequency = new Map()
    tokens.forEach((token) => {
      termFrequency.set(token, (termFrequency.get(token) || 0) + 1)
    })

    for (const [term, tf] of termFrequency.entries()) {
      if (!vocabulary.has(term)) {
        vocabulary.set(term, [])
      }
      vocabulary.get(term).push([docId, tf])
    }
  })

  return {
    docs,
    avgDocLength: docs.length > 0 ? totalLength / docs.length : 0,
    vocabulary: Object.fromEntries(Array.from(vocabulary.entries()).sort(([a], [b]) => a.localeCompare(b))),
  }
}

// The embedding model, loaded on first use, so a caller that passes its own never loads @huggingface/transformers.
const loadEmbedder = async () => {
  const { pipeline } = await import('@huggingface/transformers')
  return pipeline('feature-extraction', 'Xenova/all-MiniLM-L6-v2')
}

/**
 * Reads codex-index.json under root and writes codex-search.json there. createEmbedder resolves to a function that
 * takes a text and the pooling options and returns a tensor whose data is the text's embedding.
 */
export async function buildSearchIndex({ root = process.cwd(), createEmbedder = loadEmbedder } = {}) {
  const indexPath = path.join(root, 'codex-index.json')
  const outputPath = path.join(root, 'codex-search.json')

  if (!fs.existsSync(indexPath)) {
    throw new Error(`Missing codex-index.json at ${indexPath}. Run "npm run index" first.`)
  }

  const rawIndex = fs.readFileSync(indexPath, 'utf8')
  const entries = JSON.parse(rawIndex)
  if (!Array.isArray(entries) || entries.length === 0) {
    throw new Error('codex-index.json is empty or malformed.')
  }

  console.log(`📚 Building search data for ${entries.length} threads...`)

  const { docs, avgDocLength, vocabulary } = buildPostings(entries)

  const embedder = await createEmbedder()
  let embeddingSize = 0
  let embeddingArray = null

  for (let docId = 0; docId < entries.length; docId += 1) {
    const entry = entries[docId]
    const { title, summary } = docs[docId]
    const textSource = [title, summary, entry.content || ''].filter(Boolean).join('\n').slice(0, 8000)

    const embeddingInput = summary ? `${title}. ${summary}` : textSource || title
    const tensor = await embedder(embeddingInput || 'frame codex', {
      pooling: 'mean',
      normalize: true,
    })
    const vector = tensor.data

    if (!embeddingSize) {
      embeddingSize = vector.length
    }
    if (!embeddingArray) {
      embeddingArray = new Float32Array(entries.length * embeddingSize)
    }

    embeddingArray.set(vector, docId * embeddingSize)

    if (docId % 50 === 0) {
      console.log(`   • Processed ${docId + 1}/${entries.length} strands`)
    }
  }

  const slicedEmbeddings =
    embeddingSize > 0 && embeddingArray ? embeddingArray.subarray(0, entries.length * embeddingSize) : new Float32Array()
  const embeddingsBase64 = Buffer.from(slicedEmbeddings.buffer).toString('base64')

  const searchIndex = {
    generatedAt: new Date().toISOString(),
    stats: {
      totalDocs: entries.length,
      avgDocLength,
      vocabularySize: Object.keys(vocabulary).length,
    },
    docs,
    vocabulary,
    embeddings: {
      size: embeddingSize,
      data: embeddingsBase64,
    },
  }

  fs.writeFileSync(outputPath, JSON.stringify(searchIndex))
  const fileSizeKb = (fs.statSync(outputPath).size / 1024).toFixed(1)
  console.log(`✅ Wrote ${outputPath} (${fileSizeKb} KB, vocab ${searchIndex.stats.vocabularySize})`)
  return searchIndex
}
